-- Product analytics wiki section (sibling of "Data modeling").
-- Idempotent: pages upsert by slug (no-op if already present); parent wiring and
-- wikilinks are join-based and safe to re-run. Run after seed.sql + seed_wiki.sql
-- so the cross-links into the data-modeling concepts resolve.
-- Mirrors what was seeded to the live DB via the Supabase MCP (2026-06).

insert into pages (title, slug, kind, content, visibility) values ('Product analytics', 'product-analytics', 'wiki', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Product analytics is how you understand what people actually do in your product, from the raw events they generate. It's the behavioral lens, and it sits next to "},{"type":"wikilink","attrs":{"title":"Data modeling"}},{"type":"text","text":" as a discipline. Data modeling is about meaning and structure in the warehouse. Product analytics is about behavior. The two meet at the semantic layer."}]},{"type":"paragraph","content":[{"type":"text","text":"This section has two halves, the same shape as the data-modeling section: the theory of how behavioral data works, and the practice of running it in a real org."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Theory"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Foundations — ","marks":[{"type":"bold"}]},{"type":"text","text":"what product analytics is and why it matters, and the event as the atom of behavior."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Design — ","marks":[{"type":"bold"}]},{"type":"text","text":"event design and naming, taxonomy and ontology, identity and sessions, tracking plans."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use — ","marks":[{"type":"bold"}]},{"type":"text","text":"the metrics that matter, how events become models, and experimentation."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Practice"}]},{"type":"paragraph","content":[{"type":"text","text":"Instrumentation, the platform landscape, governance, privacy, team models, and how it all connects back to the warehouse."}]},{"type":"paragraph","content":[{"type":"text","text":"The through-line is the same one taro is built on: clean events, defined once, owned, that both people and machines can trust."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"What product analytics is"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Product analytics practice"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Voices and canon"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('What product analytics is', 'what-product-analytics-is', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Product analytics is the study of behavior inside a product, built from a stream of events. It answers a specific kind of question: what do users do, in what order, and does it lead to value."}]},{"type":"paragraph","content":[{"type":"text","text":"It's easy to confuse with its neighbors, so draw the lines clearly:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"vs business intelligence — ","marks":[{"type":"bold"}]},{"type":"text","text":"BI reports on aggregate business state (revenue, pipeline, headcount). Product analytics reports on individual behavior over time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"vs marketing attribution — ","marks":[{"type":"bold"}]},{"type":"text","text":"tools like Bizible attribute pipeline and revenue to marketing touches. That's channels and spend, not in-product behavior."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"vs data modeling — ","marks":[{"type":"bold"}]},{"type":"text","text":"data modeling gives behavior structure and meaning in the warehouse. Product analytics is the lens you point at it."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The atom is the "},{"type":"wikilink","attrs":{"title":"The event"}},{"type":"text","text":". The questions are funnels, retention, activation, and paths. The job is turning a firehose of clicks into a trustworthy picture of whether the product works."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Why product analytics matters"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The event"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Metrics that matter"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Why product analytics matters', 'why-product-analytics-matters', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Without it you ship on opinion. With it you ship on evidence: where users drop off, what predicts retention, which features get used and which just got built."}]},{"type":"paragraph","content":[{"type":"text","text":"The decisions it drives are the ones that actually move the business. What to build next. What's working. Where the funnel leaks. What an activated user looks like, and how to get more of them. Product analytics is only useful when it connects to growth, so tie every event back to a decision someone makes."}]},{"type":"paragraph","content":[{"type":"text","text":"There's a failure mode worse than having no analytics: having bad analytics. Messy events give confident wrong answers, and a wrong number people trust is more expensive than no number at all. That's why the design and governance chapters matter as much as the metrics."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"What product analytics is"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Metrics that matter"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Governance and data quality"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('The event', 'the-event', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An event is the atom of product analytics. It's a thing that happened: an actor, an action, a timestamp, and some properties. "},{"type":"text","text":"User 123 completed checkout at 10:04, cart value 48.00.","marks":[{"type":"italic"}]},{"type":"text","text":" Actions are written in past tense because they already happened."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Events, properties, and traits"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Event — ","marks":[{"type":"bold"}]},{"type":"text","text":"the action. If you know databases, an event is like a table."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Property — ","marks":[{"type":"bold"}]},{"type":"text","text":"context on that one action (cart value, page name). Like columns on the table."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"User property / trait — ","marks":[{"type":"bold"}]},{"type":"text","text":"an attribute of the actor (plan, signup date), not of a single action."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Events arrive as an append-only stream. The "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":" of that stream is one row per thing that happened, and getting that grain right is what keeps every downstream count honest."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Event design and naming"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Identity and sessions"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Event design and naming', 'event-design-and-naming', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Good event data is designed, not accumulated. The dominant convention is object plus action in past tense: "},{"type":"text","text":"Product Viewed","marks":[{"type":"italic"}]},{"type":"text","text":", "},{"type":"text","text":"Order Completed","marks":[{"type":"italic"}]},{"type":"text","text":". Pick one casing standard and enforce it. Segment uses Title Case events with snake_case properties; Amplitude and Mixpanel default to snake_case verb-noun. The structure is what matters: one object, one past-tense action."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The rules that save you"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Context goes in properties — ","marks":[{"type":"bold"}]},{"type":"text","text":"track Product Added with an item property, never add_shirt_to_cart and add_hoodie_to_cart. Variable values are properties, not event names."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Work top-down from metrics — ","marks":[{"type":"bold"}]},{"type":"text","text":"decide what you need to measure first, then derive the events. Bottom-up tracking gives you sprawl and gaps at the same time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep core events few and rich — ","marks":[{"type":"bold"}]},{"type":"text","text":"a working heuristic is to stay near 30 well-defined core events. Past that, people get lost and duplicate metrics creep in."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Track at the level you'll analyze — ","marks":[{"type":"bold"}]},{"type":"text","text":"not every pixel, not one giant event. Match the grain to the question."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"The event"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Taxonomy and ontology"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Tracking plans and data contracts"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Taxonomy and ontology', 'taxonomy-and-ontology', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A taxonomy is the system for naming and organizing your events and properties. An ontology is a model of the objects in your product (users, accounts, content, subscriptions) and how they relate. Events hang off that model."}]},{"type":"paragraph","content":[{"type":"text","text":"The shift the field is making is from click-first to entity-first. Instead of cataloging every button, you model the nouns of the business and derive events from them. Snowplow does this with reusable entities (formerly contexts) attached to any event; a user entity captured on a search is the same one captured on a click. It's the same idea as "},{"type":"wikilink","attrs":{"title":"Entities, instances & identifiers"}},{"type":"text","text":" in data modeling, applied to behavior."}]},{"type":"paragraph","content":[{"type":"text","text":"Entity-first design is what keeps meaning consistent across thousands of events, and it's the bridge to the warehouse, where those entities become your dimensions. It's also the foundation of a real "},{"type":"wikilink","attrs":{"title":"Semantics & the semantic layer"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Event design and naming"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Identity and sessions"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Entities, instances & identifiers"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Semantics & the semantic layer"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Identity and sessions', 'identity-and-sessions', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Most behavior happens before you know who someone is, so identity is the hard part of product analytics. You track an anonymous id first, then tie it to a real one when the person signs in."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The grains of identity"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"device — ","marks":[{"type":"bold"}]},{"type":"text","text":"an anonymous id (cookie, generated UUID) for someone you don't recognize yet."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"user — ","marks":[{"type":"bold"}]},{"type":"text","text":"a stable id for the person. Use a database id, not an email, because emails change and ids shouldn't."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"account — ","marks":[{"type":"bold"}]},{"type":"text","text":"the org or company the user belongs to. The group call models this, and it's how B2B analysis works at all."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"An identity graph stitches the anonymous history onto the known profile when someone identifies, so their earlier visits retroactively belong to them. Sessions group a person's events into a window of activity. Increasingly you compute sessions in the warehouse rather than trusting the SDK, which keeps the logic in one governed place. This is the same identity-resolution problem the warehouse faces, just upstream."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"The event"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"From events to models"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Privacy and consent"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Tracking plans and data contracts', 'tracking-plans-and-data-contracts', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A tracking plan is the source of truth for your events: every event, its properties and types, who owns it, and why it exists. Treat it as a data contract, not a wiki page."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Spec, instrument, validate"}]},{"type":"paragraph","content":[{"type":"text","text":"The modern loop, productized by Avo and Iteratively and by Segment Protocols: spec the event in the plan, generate type-safe code so the compiler catches drift, then validate the live stream against the plan and alert when reality diverges. Snowplow enforces it at the pipeline, where invalid events are quarantined instead of silently corrupting tables."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Versioning and breaking changes"}]},{"type":"paragraph","content":[{"type":"text","text":"Additive changes are safe. Renames, removals, and type changes are breaking, so version them with a deprecation window. The subtle one: a property can keep its name and type while its meaning changes, and that is still a breaking change even though validation passes. Capture the why next to the event so the next person knows when meaning shifted."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Event design and naming"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Governance and data quality"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Metrics that matter', 'metrics-that-matter', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The point of all the events is a small set of numbers you actually steer by. The North Star framework is the cleanest version: one metric that captures the core value your product delivers, fed by a handful of input metrics that teams can directly move."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Activation — ","marks":[{"type":"bold"}]},{"type":"text","text":"the moment a new user first gets real value. Usually the highest-leverage metric to define well."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Retention — ","marks":[{"type":"bold"}]},{"type":"text","text":"do they come back. The truest signal that the product works."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Funnels — ","marks":[{"type":"bold"}]},{"type":"text","text":"where people drop off on the way to a goal."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Inputs over outputs — ","marks":[{"type":"bold"}]},{"type":"text","text":"track the levers you can pull this week, not just the lagging outcome."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Every one of these has to be defined once. The classic failure is the same metric meaning one thing in Amplitude and another in the warehouse, because the logic lives in two places. Defining it in a "},{"type":"wikilink","attrs":{"title":"Semantics & the semantic layer"}},{"type":"text","text":" is how you stop that drift. Counting cleanly is its own skill, see "},{"type":"wikilink","attrs":{"title":"Counting & aggregation"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Counting & aggregation"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Connecting to the warehouse and the semantic layer"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Experimentation"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('From events to models', 'from-events-to-models', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Raw events are not analysis. They get modeled in the warehouse into progressively richer grains: event, then session, then user and account rollups, then funnels, retention, and cohorts. Snowplow ships dbt packages that do exactly this, with the session as the atomic unit."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Two ways to model behavior"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dimensional (Kimball) — ","marks":[{"type":"bold"}]},{"type":"text","text":"events become fact tables with foreign keys to conformed dimensions. Mature, great for slice-and-dice, but you model relationships up front and behavioral sequences get join-heavy. See "}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Activity schema — ","marks":[{"type":"bold"}]},{"type":"text","text":"one tall stream of entity, activity, timestamp, with self-joins instead of foreign keys. Elegant for sequence questions, but niche now and expensive on big streams."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Where a metric is defined matters as much as how. In the tool is fast but ungoverned. In dbt is governed but rigid. In a semantic layer is defined once and read by everything. That last option is where the field is heading. Get the "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":" right at every step or the rollups lie. See also "},{"type":"wikilink","attrs":{"title":"Modeling theory"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Modeling theory"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Connecting to the warehouse and the semantic layer"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Experimentation', 'experimentation', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Experimentation is how you turn \"we think\" into \"we measured.\" An A/B test is a controlled experiment: randomize users into a control and a treatment, change one thing, and measure the difference. It rides directly on clean events and trustworthy metrics, so it belongs in product analytics, not off to the side."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Why experiment"}]},{"type":"paragraph","content":[{"type":"text","text":"Observational data shows correlation. Experiments show causation, which is the only thing that tells you a change actually caused the outcome rather than coinciding with it. Most product opinions are wrong, including confident ones, and the cheapest way to find out is to test before you commit."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Anatomy of an A/B test"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hypothesis — ","marks":[{"type":"bold"}]},{"type":"text","text":"a specific, falsifiable claim: this change will move that metric, because."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Randomization unit — ","marks":[{"type":"bold"}]},{"type":"text","text":"what gets split (user, account, session). Pick the unit that matches how the change is experienced and stick to it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Control and treatment — ","marks":[{"type":"bold"}]},{"type":"text","text":"the current experience versus the change, assigned at random so the groups are comparable."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The OEC — ","marks":[{"type":"bold"}]},{"type":"text","text":"the overall evaluation criterion, the one metric that decides the test, agreed before you start."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Guardrails — ","marks":[{"type":"bold"}]},{"type":"text","text":"metrics that must not get worse (latency, churn, revenue) even if the OEC improves."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Power and duration — ","marks":[{"type":"bold"}]},{"type":"text","text":"compute the sample size and run time you need up front. Underpowered tests waste traffic and mislead."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Trustworthy results"}]},{"type":"paragraph","content":[{"type":"text","text":"Most of the value is in not fooling yourself. The hazards, drawn from Kohavi's work:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Peeking — ","marks":[{"type":"bold"}]},{"type":"text","text":"checking results early and stopping when they look good inflates false positives. Decide the duration in advance."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sample ratio mismatch — ","marks":[{"type":"bold"}]},{"type":"text","text":"if the split isn't the ratio you set (50/50 coming out 47/53), something is broken and the result is suspect."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Practical vs statistical significance — ","marks":[{"type":"bold"}]},{"type":"text","text":"a result can be real and still too small to care about. Set a minimum effect that's worth shipping."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Novelty and primacy effects — ","marks":[{"type":"bold"}]},{"type":"text","text":"users react to change itself at first. Run long enough for the effect to settle."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Twyman's law — ","marks":[{"type":"bold"}]},{"type":"text","text":"any figure that looks too good or too surprising is probably wrong. Investigate before you celebrate."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Beyond the simple A/B"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Multivariate — ","marks":[{"type":"bold"}]},{"type":"text","text":"test several changes at once when you have the traffic to power it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Holdouts — ","marks":[{"type":"bold"}]},{"type":"text","text":"keep a slice that never gets the feature, to measure long-run impact."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Switchback / geo tests — ","marks":[{"type":"bold"}]},{"type":"text","text":"when you can't randomize users cleanly (marketplaces, network effects), randomize over time or region."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Quasi-experiments — ","marks":[{"type":"bold"}]},{"type":"text","text":"when you truly can't randomize, methods like difference-in-differences approximate it, with more assumptions and less certainty."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"How it connects to events"}]},{"type":"paragraph","content":[{"type":"text","text":"An experiment is only as trustworthy as the data under it. Assignment should be logged as an event, the OEC and guardrails should be the same metrics you define everywhere else, and serious analysis happens in the warehouse where you can audit it. Experimentation reuses the whole stack: the events, the identity model, and the metric definitions."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Program and culture"}]},{"type":"paragraph","content":[{"type":"text","text":"One test is a tactic; an experimentation program is a capability. The teams that win run many small tests, institutionalize guardrails and review, and treat a clear result as the decision-maker rather than the loudest voice. The platform is the easy part. The culture of actually deferring to the experiment is the hard part."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Metrics that matter"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The event"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Connecting to the warehouse and the semantic layer"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Voices and canon', 'voices-and-canon', 'wiki', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"There's no single Joe Reis for product analytics; the field splits into lanes. A starting map of who to read and why."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Digital and web analytics (the foundation)"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Avinash Kaushik — ","marks":[{"type":"bold"}]},{"type":"text","text":"Web Analytics 2.0 and the Occam's Razor blog; the popularizer of digital analytics."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Simo Ahava — ","marks":[{"type":"bold"}]},{"type":"text","text":"the technical reference for tracking and tag implementation."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Product analytics practice"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Adam Greco — ","marks":[{"type":"bold"}]},{"type":"text","text":"the prolific working-practitioner voice (Amplitude, then Hightouch)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"John Cutler — ","marks":[{"type":"bold"}]},{"type":"text","text":"the North Star framework; metrics culture."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Crystal Widjaja — ","marks":[{"type":"bold"}]},{"type":"text","text":"retention and instrumentation at scale (Gojek, Reforge)."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Event-data engineering and governance"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Yali Sassoon and Alex Dean — ","marks":[{"type":"bold"}]},{"type":"text","text":"Snowplow; schema-first, warehouse-native behavioral data."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Timo Dechau — ","marks":[{"type":"bold"}]},{"type":"text","text":"event modeling and entity-first design."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stef Olafsdottir / Iteratively — ","marks":[{"type":"bold"}]},{"type":"text","text":"tracking plans as a governed, version-controlled product."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Experimentation"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ronny Kohavi (with Tang and Xu) — ","marks":[{"type":"bold"}]},{"type":"text","text":"Trustworthy Online Controlled Experiments, the A/B testing bible."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Lukas Vermeer — ","marks":[{"type":"bold"}]},{"type":"text","text":"building experimentation programs and culture."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Canon and communities"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Amplitude's North Star Playbook; Segment's Analytics Academy and the Segment Spec; Snowplow's behavioral-data writing; Lean Analytics (Croll & Yoskovitz)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Communities: MeasureCamp, The Analytics Power Hour, Locally Optimistic, the dbt community for event modeling."}]}]}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Product analytics practice', 'product-analytics-practice', 'wiki', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The theory of behavioral data is the easy half. This hub is the practice: standing it up in a real organization, with real engineers, real budgets, and real politics."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Instrumentation strategy and working with product engineers."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The platform landscape and how to choose."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Governance, data quality, and privacy."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Team and ownership models, and connecting it all back to the warehouse."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Product analytics"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Connecting to the warehouse and the semantic layer"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Instrumentation strategy', 'instrumentation-strategy', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How events get into the system is a real architectural choice with three options:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Code-based (precision) — ","marks":[{"type":"bold"}]},{"type":"text","text":"each event explicitly written with structured properties. Best data, full control, but roughly half an hour of engineering per event, so it doesn't scale to everything."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Autocapture — ","marks":[{"type":"bold"}]},{"type":"text","text":"the SDK records everything automatically; you define events later, even retroactively. Great coverage and onboarding, noisy and hard to govern."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CDP-routed — ","marks":[{"type":"bold"}]},{"type":"text","text":"instrument once to a CDP that fans out and validates against the plan."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The consensus answer is to combine them: autocapture for breadth and the surprises you didn't plan for, and hand-instrument the 10 to 20 core conversion and activation events that power funnels and experiments."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Working with product engineers"}]},{"type":"paragraph","content":[{"type":"text","text":"Tracking dies when it sits in the engineering backlog behind feature work. Make the tracking-plan entry part of the definition of done, generate type-safe code so adding an event is faster than skipping it, and validate in CI and staging so a release can't quietly break a funnel."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Tracking plans and data contracts"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The platform landscape"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('The platform landscape', 'the-platform-landscape', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The tools that touch events are not one category. Sorting them is most of the battle:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CDP (collect and route) — ","marks":[{"type":"bold"}]},{"type":"text","text":"Segment, RudderStack, mParticle. Instrument once, fan out to many tools, resolve identity. Plumbing, not analysis."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Product analytics — ","marks":[{"type":"bold"}]},{"type":"text","text":"Amplitude, Mixpanel, Pendo, Heap, GA4. Answer behavioral questions: funnels, retention, paths."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Warehouse-native pipeline — ","marks":[{"type":"bold"}]},{"type":"text","text":"Snowplow. Delivers owned, schema-validated atomic events into your warehouse. Gives you data, not dashboards."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Marketing attribution — ","marks":[{"type":"bold"}]},{"type":"text","text":"Bizible / Marketo Measure. Attributes pipeline to marketing touches. A different question; included only as a boundary."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Governance and activation — ","marks":[{"type":"bold"}]},{"type":"text","text":"Avo (tracking plans), Hightouch and Census (reverse ETL back to operational tools)."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The axis that matters is who owns the event and where it lands: first-party and in a warehouse you own, versus a SaaS silo you rent. The clear 2026 trend is warehouse-native and composable: product analytics running on the warehouse instead of copying data into a silo, so every tool reads the same numbers. That's the topic of "},{"type":"wikilink","attrs":{"title":"Connecting to the warehouse and the semantic layer"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Instrumentation strategy"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Connecting to the warehouse and the semantic layer"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Governance and data quality', 'governance-and-data-quality', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bad event data is worse than none, because people trust it. Duplicate names (sign-up, sign_up, user_sign-up) split one metric into three and make conversion look broken. The accumulated mess has a name: tracking debt, the point where you can't decide well without adding more bad tracking."}]},{"type":"paragraph","content":[{"type":"text","text":"Governance is not a document, it's a system with three parts:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ownership — ","marks":[{"type":"bold"}]},{"type":"text","text":"every event has an owner. No owner means no one fixes it when it breaks."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Approval — ","marks":[{"type":"bold"}]},{"type":"text","text":"new events and changes go through review, like code, not into production by surprise."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Runtime validation — ","marks":[{"type":"bold"}]},{"type":"text","text":"the enforcement arm. Schema checks at the pipeline or pre-merge turn the tracking plan from a wish into a gate."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This is the upstream sibling of the metric-definition problem. Govern the events and the metrics have a chance; let the events rot and no semantic layer can save them."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Tracking plans and data contracts"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Privacy and consent"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Privacy and consent', 'privacy-and-consent', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Behavioral data is personal data, so privacy is part of the design, not a bolt-on. The two regimes to know: GDPR requires opt-in before non-essential tracking, and CCPA/CPRA centers opt-out and do-not-sell. A consent management platform captures and enforces those choices, and consent mode gates or anonymizes collection based on them."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Minimize PII — ","marks":[{"type":"bold"}]},{"type":"text","text":"prefer pseudonymous database ids over emails in event properties. This is the same advice as stable user ids in "}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Retention and residency — ","marks":[{"type":"bold"}]},{"type":"text","text":"know how long you keep behavioral data and where it lives across regions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Know where it is — ","marks":[{"type":"bold"}]},{"type":"text","text":"you can't govern PII you can't find. Inventory it across the CDP, the tools, and the warehouse."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Done well, privacy and good event design point the same way: fewer, cleaner, well-owned events with PII kept out of the properties."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Identity and sessions"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Governance and data quality"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Team and ownership models', 'team-and-ownership-models', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Product analytics sits at an intersection: product managers decide what to measure, engineers instrument it, analytics engineers model it, and growth uses it. That diffuse ownership is itself the most common failure mode."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Centralized, embedded, hybrid"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Centralized — ","marks":[{"type":"bold"}]},{"type":"text","text":"one team, consistent standards, but it becomes a ticket queue disconnected from product priorities."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Embedded — ","marks":[{"type":"bold"}]},{"type":"text","text":"analysts inside product teams, fast and contextual, but knowledge fragments and metric logic gets duplicated."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hub-and-spoke — ","marks":[{"type":"bold"}]},{"type":"text","text":"a central team owns standards and the platform, embedded analysts own their domain. Balances both if roles are framed well."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The deeper lesson: don't treat the org chart as the lever for data culture. Invest in systems instead, shared models, codified definitions, version control and CI-style rigor. In practice analytics engineering should own the modeled event marts and the semantic layer (the definitions), while product and growth consume them through the tool."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Governance and data quality"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Connecting to the warehouse and the semantic layer"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Connecting to the warehouse and the semantic layer', 'connecting-warehouse-semantic-layer', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This is where product analytics and "},{"type":"wikilink","attrs":{"title":"Data modeling"}},{"type":"text","text":" actually meet. The recurring problem: a product-analytics tool recomputes its own metrics from the event stream, so active users in Amplitude legitimately differs from active users in the warehouse. Two engines over the same events, two answers, and a meeting that goes nowhere."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Make the warehouse the source of truth"}]},{"type":"paragraph","content":[{"type":"text","text":"Two ways to collapse the two engines into one. Push warehouse-computed metrics into the tool, or point the tool directly at warehouse tables (warehouse-native product analytics). Both make the warehouse canonical and stop the drift."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The semantic layer as the meeting point"}]},{"type":"paragraph","content":[{"type":"text","text":"The real fix is a "},{"type":"wikilink","attrs":{"title":"Semantics & the semantic layer"}},{"type":"text","text":" that defines each metric once, in code, and serves it to BI, the product-analytics tool, and increasingly to AI agents. A metric defined once can't disagree with itself. This is taro's whole thesis applied to behavior: define meaning once, model it for humans and machines, and let everything read from it."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Where it's going"}]},{"type":"paragraph","content":[{"type":"text","text":"Warehouse-native product analytics, composable CDPs assembled from best-of-breed parts on the warehouse, and agents that answer behavioral questions, but only if the metrics they read are governed. The semantic layer is becoming the shared contract between product analytics, the warehouse, and AI."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Semantics & the semantic layer"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"From events to models"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Metrics that matter"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
